def fit2(deg):
    cols=[t**k for k in range(deg+1)]+[t**k*A**3 for k in range(deg+1)]+[t**k*A for k in range(deg+1)]
    X=np.array(cols).T
    c=np.linalg.lstsq(X,dA_dt,rcond=None)[0]
    r=X@c-dA_dt
    return np.sum(r**2)/np.sum((dA_dt-dA_dt.mean())**2)
